-- HVI CRM — NECA Potential Leads: web-researched qualification for the top A-tier companies
-- Run AFTER the data_neca_leads_0X.sql imports. Sources: public company pages, press releases and job postings (web search, Oct 2026).
-- Figures are approximate and should be verified before outreach; contacts are from public company pages and may be stale.

UPDATE neca_leads SET qualification_status = 'researched', tier = 'A', employee_estimate = '~8,000 (company press release)', score_rationale = 'Rosendin is a large, employee-owned (ESOP) electrical contractor headquartered in San Jose, CA, with about 27 NECA listings across many chapters and states. Scale, multi-region crews, and an ESOP culture (employee pride) make it a strong fit for branded, fully custom apparel.', buying_signals = 'Moved into a new ~$23M San Jose headquarters (Sept 2025); CEO transition (Keith Douglas, Jan 2024); active corporate marketing/communications function that includes employee communications for ESOP participants; recognized as a top workplace in several regions.', suggested_angle = 'Congrats on the new San Jose HQ — we make fully custom button-ups for electrical contractors and thought your teams could be a great fit for employee and event apparel.', contacts = '[{"role": "buyer", "name": "Salina Brown", "title": "Director of Corporate Marketing", "reason": "Listed on a 2023 Rosendin company page \u2014 verify she is still in role."}, {"role": "champion", "name": "Maira Ollila", "title": "Director of Corporate Communications", "reason": "Listed in Rosendin media kit as media contact \u2014 verify current."}]'::jsonb
WHERE neca_key = 'rosendin electric';
UPDATE neca_leads SET qualification_status = 'researched', tier = 'A', employee_estimate = 'Sources conflict (184 to 5,000+); company site mentions offices in 9 states', score_rationale = 'ArchKey is the largest electrical contractor in Missouri per public sources, operating in multiple states under several legacy brands (e.g., Sachs Electric). Multiple NECA chapter listings and a multi-office footprint indicate real scale. Ownership appears to be private-equity backed (One Rock Capital / 26North per public profiles), NOT Quanta as assumed in the brief — verify before using any "Quanta connection" angle.', buying_signals = 'Rebranded legacy contractors into one national brand (brand-consolidation moment = natural time to refresh employee apparel). Hiring/estimating roles posted publicly.', suggested_angle = 'Saw ArchKey is bringing the family of companies under one brand — we make fully custom shirts for electrical contractors and could help the whole team wear it consistently.'
WHERE neca_key = 'archkey solutions';
UPDATE neca_leads SET qualification_status = 'researched', tier = 'A', employee_estimate = 'Not found in public sources (subsidiary of MYR Group)', score_rationale = 'Sturgeon Electric is a long-established electrical/utility contractor and a subsidiary of MYR Group, with 13 NECA listings across multiple chapters (including line constructors). Strong high-voltage fit and multi-location footprint.', buying_signals = 'Has run high-school open houses and college outreach to recruit into the trade; MYR Group runs apprenticeship (partnered with NECA) and internship programs. No recent (2025-26) event announcements found.', suggested_angle = 'Your recruiting open houses and apprenticeship work are exactly where a sharp, custom-fit company shirt makes a difference — we make them for electrical contractors.'
WHERE neca_key = 'sturgeon electric';
UPDATE neca_leads SET qualification_status = 'researched', tier = 'A', employee_estimate = 'Michels Corporation: 9,000+ employees (company site)', score_rationale = 'Michels Power is the transmission & distribution arm of Michels Corporation (ENR-ranked #1 T&D power contractor per company materials). Very strong fit: high-voltage work, thousands of employees, and a culture that celebrates its people.', buying_signals = 'Recurring employee-recognition events (e.g., Oct 2025 celebration of 20 employees with 550 combined years of service, incl. Michels Power staff); "Best Place to Work" recognition; Culture Manager role that oversees planned events; ~$5,000/employee in annual training; strong veteran-hiring program.', suggested_angle = 'Saw the recent service-anniversary celebration — custom button-ups for milestone years and crew events are exactly what we build for electrical contractors.'
WHERE neca_key = 'michels power';
UPDATE neca_leads SET qualification_status = 'researched', tier = 'A', employee_estimate = '3,000+ (company job posting); HQ Logan, UT; privately/family held', score_rationale = 'Large, family-held electrical contractor (HQ Logan, UT) with a multi-state footprint and a 3,000+ employee organization. Multiple NECA listings and a strong "CVE family" culture message make it a good fit for branded apparel.', buying_signals = 'Has marked 100+ years in business (ECM article); family-culture messaging; multi-state expansion.', suggested_angle = 'A century-plus family company deserves apparel that shows it — we make fully custom shirts for electrical contractors.'
WHERE neca_key = 'cache valley electric';
UPDATE neca_leads SET qualification_status = 'researched', tier = 'A', employee_estimate = '2,000+ (company job-posting boilerplate)', score_rationale = 'Service Electric (Chattanooga, TN) is a Quanta Services subsidiary per its own job postings, with 2,000+ employees, a Southeast/Midwest/Puerto Rico footprint, and storm-restoration crews nationwide. Strong high-voltage/utility fit AND a Quanta-ecosystem connection from Tony''s criteria.', buying_signals = 'Quanta subsidiary (ecosystem connection); active hiring; nationwide storm-restoration deployments.', suggested_angle = 'We build custom shirts for linemen and utility crews — and your storm-restoration teams travel in your colors.'
WHERE neca_key = 'service electric';

SELECT company, tier, qualification_status FROM neca_leads WHERE qualification_status = 'researched' ORDER BY company;
